/**
 * 运营列表页：新建智能体 / 第三方接入 — 遮罩 + iframe 悬浮弹窗
 */
(function (global) {
  var overlay = null;
  var frame = null;

  function getOverlay() {
    if (!overlay) overlay = document.getElementById('opsModalOverlay');
    return overlay;
  }

  function getFrame() {
    if (!frame) frame = document.getElementById('opsModalFrame');
    return frame;
  }

  function openModal(page, extraQuery) {
    var el = getOverlay();
    var fr = getFrame();
    if (!el || !fr) return;
    var q = 'embed=1';
    if (extraQuery) q += '&' + extraQuery.replace(/^\?/, '');
    fr.src = page + '?' + q;
    el.classList.add('active');
    el.setAttribute('aria-hidden', 'false');
    document.body.classList.add('ops-modal-open');
  }

  function closeModal(refresh) {
    var el = getOverlay();
    var fr = getFrame();
    if (el) {
      el.classList.remove('active');
      el.setAttribute('aria-hidden', 'true');
    }
    if (fr) fr.src = 'about:blank';
    document.body.classList.remove('ops-modal-open');
    if (refresh && typeof global.refreshAgentList === 'function') {
      global.refreshAgentList();
    }
    var u = new URL(window.location.href);
    if (u.searchParams.has('open')) {
      u.searchParams.delete('open');
      history.replaceState(null, '', u.pathname + (u.search || '') + u.hash);
    }
  }

  function openCreate(extra) {
    openModal('04-create-modal.html', extra || '');
  }

  function openThirdParty(extra) {
    openModal('third-party-register.html', extra || '');
  }

  function wireButtons() {
    var btnCreate = document.getElementById('btnOpenCreate');
    var btnThird = document.getElementById('btnOpenThirdParty');
    if (btnCreate) {
      btnCreate.addEventListener('click', function (e) {
        e.preventDefault();
        openCreate();
      });
    }
    if (btnThird) {
      btnThird.addEventListener('click', function (e) {
        e.preventDefault();
        openThirdParty();
      });
    }
    var overlayEl = getOverlay();
    if (overlayEl) {
      overlayEl.addEventListener('click', function (e) {
        if (e.target === overlayEl) closeModal(false);
      });
    }
  }

  function handleMessage(event) {
    if (!event || !event.data) return;
    var data = event.data;
    if (typeof data === 'string') {
      if (data === 'ops-modal-close') closeModal(false);
      if (data === 'ops-modal-close-refresh') closeModal(true);
    } else if (data && data.type === 'ops-modal') {
      if (data.action === 'close') closeModal(!!data.refresh);
    }
  }

  function openFromQuery() {
    var open = global.Proto ? Proto.params().get('open') : new URLSearchParams(location.search).get('open');
    if (open === 'create') openCreate(location.search.replace(/^\?/, '').replace(/(?:^|&)open=create&?/, '').replace(/^&/, ''));
    else if (open === 'third-party' || open === 'thirdparty') {
      openThirdParty(location.search.replace(/^\?/, '').replace(/(?:^|&)open=(?:third-party|thirdparty)&?/, '').replace(/^&/, ''));
    }
  }

  function initOpsListModals() {
    wireButtons();
    window.addEventListener('message', handleMessage);
    openFromQuery();
  }

  global.OpsListModals = {
    init: initOpsListModals,
    openCreate: openCreate,
    openThirdParty: openThirdParty,
    close: closeModal
  };

  /** iframe 内页调用：关闭遮罩 */
  global.closeOpsEmbedModal = function (refresh) {
    if (window.parent && window.parent !== window) {
      window.parent.postMessage(refresh ? 'ops-modal-close-refresh' : 'ops-modal-close', '*');
      return true;
    }
    return false;
  };
})(window);

