.ops-dash-kpi-red .ops-dash-kpi-icon { background: #fef2f2; }
.ops-dash-kpi-yellow .ops-dash-kpi-icon { background: #fffbeb; }
.ops-dash-kpi-green .ops-dash-kpi-icon { background: #ecfdf5; }
.ops-dash-kpi-label { font-size: 12px; color: var(--text-muted); margin-bottom: 4px; }
