}
.ops-dash-legend li:last-child { border-bottom: none; }
.ops-dash-legend-dot { width: 8px; height: 8px; border-radius: 50%; margin-right: 8px; display: inline-block; }
.ops-dash-subsection h4 { font-size: 13px; font-weight: 600; margin: 0 0 10px; }
.ops-dash-event { padding: 10px 0; border-top: 1px solid var(--border-light, #f3f4f6); }
.ops-dash-event:first-child { border-top: none; padding-top: 0; }
.ops-dash-event-title { font-size: 13px; font-weight: 500; margin-bottom: 4px; }
.ops-dash-event-meta { font-size: 12px; color: var(--text-muted); }
.ops-dash-event-meta a { color: var(--primary); text-decoration: none; }
.ops-dash-chart-wrap { margin-bottom: 12px; }
.ops-dash-line-chart { width: 100%; height: auto; display: block; }
.ops-dash-chart-labels {
  display: flex; justify-content: space-between; font-size: 10px; color: var(--text-muted);
  padding: 0 4px; margin-top: 4px;
}
.ops-dash-chart-legend { display: flex; gap: 16px; font-size: 11px; color: var(--text-muted); margin-top: 8px; }
.ops-dash-chart-legend .legend-rt::before,
.ops-dash-chart-legend .legend-batch::before {
  content: ''; display: inline-block; width: 16px; height: 2px; margin-right: 6px; vertical-align: middle;
}
.ops-dash-chart-legend .legend-rt::before { background: #3b82f6; }
.ops-dash-chart-legend .legend-batch::before {
  background: #10b981; border-top: 2px dashed #10b981; height: 0;
}
.ops-dash-trend-meta { display: flex; gap: 24px; padding-top: 12px; border-top: 1px solid var(--border); }
.ops-dash-meta-item { display: flex; flex-direction: column; }
.ops-dash-meta-val { font-size: 20px; font-weight: 600; }
.ops-dash-meta-lbl { font-size: 11px; color: var(--text-muted); margin-top: 2px; }
.ops-row-actions { display: flex; flex-wrap: wrap; gap: 4px 8px; align-items: center; }
.ops-actions-cell { white-space: nowrap; }
.btn-link-primary {
  background: none; border: none; padding: 0; font-size: 12px; color: var(--primary);
  cursor: pointer; text-decoration: none;
}
.btn-link-muted {
  background: none; border: none; padding: 0; font-size: 12px; color: var(--text-muted);
  cursor: pointer;
}
.btn-link-danger {
  background: none; border: none; padding: 0; font-size: 12px; color: #dc2626;
  cursor: pointer;
}
.btn-link-primary:hover { text-decoration: underline; }
.btn-link-danger:hover { text-decoration: underline; }
.ops-offline-modal {
  position: fixed; inset: 0; z-index: 1200; background: rgba(15, 23, 42, 0.45);
  display: none; align-items: center; justify-content: center;
}
.ops-offline-modal.show { display: flex; }
.ops-offline-dialog {
  background: var(--bg-white); border-radius: var(--radius-md); padding: 24px;
