}
.ops-offline-dialog h3 { margin: 0 0 8px; font-size: 16px; }
.ops-offline-dialog p { margin: 0 0 20px; font-size: 13px; color: var(--text-muted); line-height: 1.5; }
.ops-offline-actions { display: flex; justify-content: flex-end; gap: 8px; }
@media (max-width: 1100px) {
  .ops-dash-kpis { grid-template-columns: repeat(2, 1fr); }
  .ops-dash-panels { grid-template-columns: 1fr; }
}

