/**
 * 智能体运营列表页 — 运营看板（生命周期 / 审核 / 治理）+ 下架确认
 */
(function (global) {
  var pendingOfflineId = null;

  var STATUS_META = {
    published: { label: '已上架', color: '#2563eb', class: 'tag-published' },
    review: { label: '审核中', color: '#d97706', class: 'tag-review' },
    pending: { label: '待上架', color: '#7c3aed', class: 'tag-pending' },
    dev: { label: '开发中', color: '#64748b', class: 'tag-dev' },
    offline: { label: '已下架', color: '#94a3b8', class: 'tag-offline' },
    disabled: { label: '已停用', color: '#dc2626', class: 'tag-offline' },
    rejected: { label: '已驳回', color: '#dc2626', class: 'tag-offline' }
  };

  var FEED_ITEMS = [
    { agentId: 'agt_procure', name: '采购申请助手', action: '提交全公司发布审核', status: 'review', time: '05-21 15:33', link: '08-audit-queue.html' },
    { agentId: 'agt_analytics', name: '数据分析助手', action: '待完成首次配置后发布', status: 'pending', time: '05-22 11:20', link: '06-dev-editor.html?new=1&id=agt_analytics&name=数据分析助手&type=qa' },
    { agentId: 'agt_daily', name: '日报生成器', action: '开发中，尚未提交发布', status: 'dev', time: '05-20 08:55', link: '05-agent-detail.html?id=agt_daily&name=日报生成器&type=qa' },
    { agentId: 'agt_leave', name: '请假审批流程', action: '已下架，用户不可访问', status: 'offline', time: '05-19 13:10', link: '05-agent-detail.html?id=agt_leave&name=请假审批流程&type=flow&tab=release' }
  ];

  function countByStatus() {
    var counts = { published: 0, disabled: 0, review: 0, dev: 0, pending: 0, offline: 0, rejected: 0 };
    var platform = 0;
    var thirdparty = 0;
    var total = 0;
    Proto.DEMO_LIST_AGENTS.forEach(function (a, i) {
      var st = Proto.resolveAgentListStatus(a.id, i);
      counts[st] = (counts[st] || 0) + 1;
      if (a.source === 'thirdparty') thirdparty++; else platform++;
      total++;
    });
    Proto.getRegistry().filter(function (x) { return x.userCreated; }).forEach(function (a) {
      var st = Proto.resolveAgentListStatus(a.id);
      counts[st] = (counts[st] || 0) + 1;
      if (a.source === 'thirdparty') thirdparty++; else platform++;
      total++;
    });
    return { counts: counts, total: total, platform: platform, thirdparty: thirdparty };
  }

  function computeMetrics() {
    var c = countByStatus();
    var published = c.counts.published || 0;
    var review = c.counts.review || 0;
    var todoPublish = (c.counts.dev || 0) + (c.counts.pending || 0);
    var governed = (c.counts.offline || 0) + (c.counts.disabled || 0) + (c.counts.rejected || 0);
    return {
      total: c.total,
      published: published,
      review: review,
      todoPublish: todoPublish,
      governed: governed,
      platform: c.platform,
      thirdparty: c.thirdparty,
      counts: c.counts
    };
  }

  function renderKpis(m) {
    var el = document.getElementById('opsDashKpis');
    if (!el) return;
    el.innerHTML =
      '<div class="ops-dash-kpi ops-dash-kpi-blue">' +
        '<div class="ops-dash-kpi-icon">✅</div>' +
        '<div class="ops-dash-kpi-body">' +
          '<div class="ops-dash-kpi-label">已上架</div>' +
          '<div class="ops-dash-kpi-val">' + m.published + '</div>' +
          '<div class="ops-dash-kpi-sub">用户可按权限访问</div>' +
        '</div>' +
      '</div>' +
      '<div class="ops-dash-kpi ops-dash-kpi-orange">' +
        '<div class="ops-dash-kpi-icon">📋</div>' +
        '<div class="ops-dash-kpi-body">' +
          '<div class="ops-dash-kpi-label">待审核发布</div>' +
          '<div class="ops-dash-kpi-val">' + m.review + '</div>' +
          '<div class="ops-dash-kpi-sub">需运营/审核人员处理</div>' +
        '</div>' +
        (m.review > 0 ? '<a href="08-audit-queue.html" class="ops-dash-pill ops-dash-pill-orange">去审核</a>' : '') +
      '</div>' +
      '<div class="ops-dash-kpi ops-dash-kpi-purple">' +
        '<div class="ops-dash-kpi-icon">🛠️</div>' +
        '<div class="ops-dash-kpi-body">' +
          '<div class="ops-dash-kpi-label">待配置 / 待发布</div>' +
          '<div class="ops-dash-kpi-val">' + m.todoPublish + '</div>' +
          '<div class="ops-dash-kpi-sub">开发中或待上架</div>' +
        '</div>' +
      '</div>' +
      '<div class="ops-dash-kpi ops-dash-kpi-gray">' +
        '<div class="ops-dash-kpi-icon">⏸️</div>' +
        '<div class="ops-dash-kpi-body">' +
          '<div class="ops-dash-kpi-label">已治理</div>' +
          '<div class="ops-dash-kpi-val">' + m.governed + '</div>' +
          '<div class="ops-dash-kpi-sub">下架 · 停用 · 驳回</div>' +
        '</div>' +
      '</div>';
  }

  function renderLifecycle(m) {
    var el = document.getElementById('opsDashLifecycle');
    if (!el) return;
    var order = ['published', 'review', 'pending', 'dev', 'offline', 'disabled', 'rejected'];
    var max = Math.max.apply(null, order.map(function (k) { return m.counts[k] || 0; }).concat([1]));
    var bars = order.filter(function (k) { return (m.counts[k] || 0) > 0; }).map(function (k) {
      var meta = STATUS_META[k];
      var n = m.counts[k] || 0;
      var pct = Math.round((n / m.total) * 100);
      var h = Math.max(8, Math.round((n / max) * 100));
      return '<div class="ops-dash-bar-item">' +
        '<div class="ops-dash-bar-track"><div class="ops-dash-bar-fill" style="height:' + h + '%;background:' + meta.color + ';"></div></div>' +
        '<div class="ops-dash-bar-num">' + n + '</div>' +
        '<div class="ops-dash-bar-lbl">' + meta.label + '</div>' +
        '<div class="ops-dash-bar-pct">' + pct + '%</div>' +
      '</div>';
    }).join('');
    el.innerHTML = bars || '<p class="ops-dash-empty">暂无智能体</p>';
  }

  function renderSource(m) {
    var el = document.getElementById('opsDashSource');
    if (!el) return;
    var tp = m.thirdparty || 0;
    var pf = m.platform || m.total - tp;
    var tpPct = m.total ? Math.round((tp / m.total) * 100) : 0;
    var pfPct = 100 - tpPct;
    el.innerHTML =
      '<div class="ops-dash-source-row">' +
        '<span><span class="ops-dash-legend-dot" style="background:#2563eb;"></span>平台创建</span>' +
        '<strong>' + pf + ' <small>(' + pfPct + '%)</small></strong>' +
      '</div>' +
      '<div class="ops-dash-source-row">' +
        '<span><span class="ops-dash-legend-dot" style="background:#10b981;"></span>第三方接入</span>' +
        '<strong>' + tp + ' <small>(' + tpPct + '%)</small></strong>' +
      '</div>' +
      '<div class="ops-dash-source-bar">' +
        '<div class="ops-dash-source-seg platform" style="width:' + pfPct + '%;"></div>' +
        '<div class="ops-dash-source-seg thirdparty" style="width:' + tpPct + '%;"></div>' +
      '</div>';
  }

  function renderFeed() {
    var el = document.getElementById('opsDashFeed');
    if (!el) return;
    el.innerHTML = FEED_ITEMS.map(function (item) {
      var meta = STATUS_META[item.status] || STATUS_META.dev;
      var st = Proto.resolveAgentListStatus(item.agentId);
      if (st !== item.status && item.agentId) {
        if (st === 'published' && item.status === 'offline') item = Object.assign({}, item, { action: '已重新上架', status: 'published' });
        else if (st === 'offline') item = Object.assign({}, item, { action: '已下架，用户不可访问', status: 'offline' });
        else if (st === 'disabled') item = Object.assign({}, item, { action: '已停用', status: 'disabled' });
        meta = STATUS_META[st] || meta;
      }
      return '<div class="ops-dash-feed-item">' +
        '<div class="ops-dash-feed-main">' +
          '<span class="tag ' + meta.class + '" style="font-size:11px;">' + meta.label + '</span>' +
          '<strong>' + item.name + '</strong>' +
          '<span class="ops-dash-feed-action">' + item.action + '</span>' +
        '</div>' +
        '<div class="ops-dash-feed-meta">' + item.time +
          ' · <a href="' + item.link + '">查看</a></div>' +
      '</div>';
    }).join('');
  }

  function renderQuickLinks(m) {
    var el = document.getElementById('opsDashQuickLinks');
    if (!el) return;
    el.innerHTML =
      '<a href="08-audit-queue.html" class="ops-dash-quick">审核工作台' + (m.review ? ' (' + m.review + ')' : '') + '</a>' +
      '<a href="index.html?open=create" class="ops-dash-quick">新建智能体</a>' +
      '<a href="index.html?open=third-party" class="ops-dash-quick">第三方接入</a>';
  }

  function refresh() {
    var m = computeMetrics();
    renderKpis(m);
    renderLifecycle(m);
    renderSource(m);
    renderFeed();
    renderQuickLinks(m);
  }

  function confirmOffline(agentId) {
    pendingOfflineId = agentId;
    var mask = document.getElementById('opsOfflineModal');
    if (!mask) {
      Proto.setState({ status: 'offline' }, agentId);
      Proto.toast('已下架');
      Proto.refreshAgentListRow(agentId);
      return;
    }
    mask.classList.add('show');
    mask.setAttribute('aria-hidden', 'false');
  }

  function hideOfflineModal() {
    pendingOfflineId = null;
    var mask = document.getElementById('opsOfflineModal');
    if (mask) {
      mask.classList.remove('show');
      mask.setAttribute('aria-hidden', 'true');
    }
  }

  function wireOfflineModal() {
    var mask = document.getElementById('opsOfflineModal');
    if (!mask || mask.dataset.wired) return;
    mask.dataset.wired = '1';
    mask.querySelectorAll('[data-offline-cancel]').forEach(function (btn) {
      btn.addEventListener('click', hideOfflineModal);
    });
    var confirm = mask.querySelector('[data-offline-confirm]');
    if (confirm) {
      confirm.addEventListener('click', function () {
        if (!pendingOfflineId) return hideOfflineModal();
        Proto.setState({ status: 'offline' }, pendingOfflineId);
        Proto.toast('已下架');
        Proto.refreshAgentListRow(pendingOfflineId);
        hideOfflineModal();
      });
    }
    mask.addEventListener('click', function (e) {
      if (e.target === mask) hideOfflineModal();
    });
  }

  function init() {
    refresh();
    wireOfflineModal();
  }

  global.OpsListDashboard = {
    init: init,
    refresh: refresh,
    confirmOffline: confirmOffline,
    computeMetrics: computeMetrics
  };
})(typeof window !== 'undefined' ? window : global);

