    scope: st.scope || 'public',
    releaseVersion: st.releaseVersion || 'v1.0.0',
    releaseNote: st.releaseNote || '全公司可见发布申请'
  };
}

function ensureDemoAuditQueue() {
  DEMO_LIST_AGENTS.forEach(function (a, i) {
