  try {
    var n = parseInt(sessionStorage.getItem('proto_audit_approved_today') || '0', 10);
    return isNaN(n) ? 0 : n;
  } catch (e) { return 0; }
}

function incrementAuditApprovedToday() {
  try {
    sessionStorage.setItem('proto_audit_approved_today', String(getAuditApprovedToday() + 1));
