    offline: { label: '已下架', color: '#94a3b8', class: 'tag-offline' },
    disabled: { label: '已停用', color: '#dc2626', class: 'tag-offline' },
    rejected: { label: '已驳回', color: '#dc2626', class: 'tag-offline' }
  };

  var STATUS_FILTER_MAP = {
    '全部': null,
    '已上架': 'published',
    '待上架': 'pending',
    '审核中': 'review',
    '开发中': 'dev',
    '已下架': 'offline',
    '已驳回': 'rejected'
  };

  var FEED_ITEMS = [
    {
      agentId: 'agt_procure', name: '采购申请助手', action: '提交全公司发布审核',
      status: 'review', time: '05-21 15:33', reviewLink: true
    },
    {
      agentId: 'agt_analytics', name: '数据分析助手', action: '待完成首次配置后发布',
      status: 'pending', time: '05-22 11:20',
      link: '06-dev-editor.html?new=1&id=agt_analytics&name=数据分析助手&type=qa'
    },
    {
      agentId: 'agt_daily', name: '日报生成器', action: '开发中，尚未提交发布',
      status: 'dev', time: '05-20 08:55',
      link: '05-agent-detail.html?id=agt_daily&name=日报生成器&type=qa'
    },
    {
      agentId: 'agt_leave', name: '请假审批流程', action: '已下架，用户不可访问',
      status: 'offline', time: '05-19 13:10',
      link: '05-agent-detail.html?id=agt_leave&name=请假审批流程&type=flow&tab=release'
    }
  ];

  function countByStatus() {
    var counts = { published: 0, disabled: 0, review: 0, dev: 0, pending: 0, offline: 0, rejected: 0 };
    var platform = 0;
    var thirdparty = 0;
    var total = 0;
    var calls7d = 0;
    Proto.DEMO_LIST_AGENTS.forEach(function (a, i) {
      var st = Proto.resolveAgentListStatus(a.id, i);
      counts[st] = (counts[st] || 0) + 1;
      if (a.source === 'thirdparty') thirdparty++; else platform++;
      if (st === 'published') {
        var agentSt = Proto.getState(a.id);
        calls7d += agentSt.calls7d || 0;
      }
      total++;
    });
    Proto.getRegistry().filter(function (x) { return x.userCreated; }).forEach(function (a) {
      var st = Proto.resolveAgentListStatus(a.id);
      counts[st] = (counts[st] || 0) + 1;
      if (a.source === 'thirdparty') thirdparty++; else platform++;
      if (st === 'published') {
        var agentSt = Proto.getState(a.id);
        calls7d += agentSt.calls7d || 0;
      }
      total++;
    });
    if (counts.published > 0 && calls7d === 0) calls7d = counts.published * 128;
    return { counts: counts, total: total, platform: platform, thirdparty: thirdparty, calls7d: calls7d };
  }

  function computeMetrics() {
    var c = countByStatus();
    var published = c.counts.published || 0;
    var review = c.counts.review || 0;
    var alerts = (c.counts.review || 0) + (c.counts.rejected || 0) + (c.counts.disabled || 0);
    return {
      total: c.total,
      published: published,
      review: review,
      alerts: alerts,
      alertLevel: alerts >= 3 ? '需关注' : '正常',
      latency: published > 0 ? '42ms' : '—',
      latencyNote: published > 0 ? '已上架智能体近7日调度' : '暂无上架智能体',
      compliance: published > 0 ? '99.8%' : '—',
      complianceLevel: published > 0 ? '安全' : '—',
      calls7d: c.calls7d,
      timeouts7d: published > 0 ? Math.max(0, Math.floor(published / 4)) : 0,
      platform: c.platform,
      thirdparty: c.thirdparty,
      counts: c.counts
    };
  }

  function kpiCard(opts) {
    var pill = opts.pill
      ? (opts.pillHref
        ? '<a href="' + opts.pillHref + '" class="ops-dash-pill ' + opts.pillClass + '">' + opts.pill + '</a>'
        : '<span class="ops-dash-pill ' + opts.pillClass + '">' + opts.pill + '</span>')
      : '';
    var attrs = opts.action ? ' data-kpi-action="' + opts.action + '"' + (opts.status ? ' data-status="' + opts.status + '"' : '') : '';
    return '<div class="ops-dash-kpi ops-dash-kpi-' + opts.tone + ' ops-dash-kpi-click"' + attrs + '>' +
      '<div class="ops-dash-kpi-icon">' + opts.icon + '</div>' +
      '<div class="ops-dash-kpi-body">' +
        '<div class="ops-dash-kpi-label">' + opts.label + '</div>' +
        '<div class="ops-dash-kpi-val">' + opts.val + '</div>' +
        '<div class="ops-dash-kpi-sub">' + opts.sub + '</div>' +
      '</div>' + pill + '</div>';
  }

  function renderKpis(m) {
    var el = document.getElementById('opsDashKpis');
    if (!el) return;
    el.innerHTML =
      kpiCard({ tone: 'slate', icon: '📦', label: '智能体总量', val: m.total, sub: '平台创建 + 第三方接入', action: 'scroll-list' }) +
      kpiCard({ tone: 'blue', icon: '✅', label: '已上架', val: m.published, sub: '用户可按权限访问', action: 'filter', status: 'published' }) +
      kpiCard({
        tone: 'orange', icon: '📋', label: '待审核发布', val: m.review, sub: '需运营/审核人员处理',
        pill: m.review > 0 ? '去审核' : '', pillClass: 'ops-dash-pill-orange', pillHref: '08-audit-queue.html',
        action: 'filter', status: 'review'
      }) +
      kpiCard({
        tone: 'red', icon: '⚠️', label: '异常监控', val: m.alerts, sub: '审核积压 · 停用 · 驳回',
        pill: m.alertLevel, pillClass: m.alerts >= 3 ? 'ops-dash-pill-red' : 'ops-dash-pill-green',
        action: 'filter', status: 'review'
      }) +
      kpiCard({ tone: 'yellow', icon: '⏱️', label: '平均调度延迟', val: m.latency, sub: m.latencyNote }) +
      kpiCard({
        tone: 'green', icon: '🛡️', label: '合规通过率', val: m.compliance, sub: '发布预检与审核通过占比',
        pill: m.complianceLevel, pillClass: 'ops-dash-pill-green'
      });
    wireKpiClicks(el);
  }

  function wireKpiClicks(root) {
    root.querySelectorAll('[data-kpi-action]').forEach(function (card) {
      card.style.cursor = 'pointer';
      card.addEventListener('click', function (e) {
        if (e.target.closest('a.ops-dash-pill')) return;
        var action = card.getAttribute('data-kpi-action');
        if (action === 'scroll-list') {
          scrollToAgentList(null);
        } else if (action === 'filter') {
          scrollToAgentList(card.getAttribute('data-status'));
        }
      });
    });
  }

  function scrollToAgentList(statusKey) {
    var section = document.getElementById('agentListSection');
    if (section) section.scrollIntoView({ behavior: 'smooth', block: 'start' });
    if (statusKey) applyStatusFilter(statusKey);
  }

  function applyStatusFilter(statusKey) {
    var pills = document.querySelectorAll('[data-status-filter-group] .filter-pills button');
    var label = null;
    Object.keys(STATUS_FILTER_MAP).forEach(function (k) {
      if (STATUS_FILTER_MAP[k] === statusKey) label = k;
    });
    pills.forEach(function (btn) {
      var match = label ? btn.textContent.trim() === label : btn.textContent.trim() === '全部';
      btn.classList.toggle('active', !!match);
    });
    filterListRows(statusKey);
  }

  function filterListRows(statusKey) {
    document.querySelectorAll('.data-table tbody tr').forEach(function (tr) {
      if (!statusKey) {
        tr.classList.remove('ops-row-hidden');
        return;
      }
      tr.classList.toggle('ops-row-hidden', tr.getAttribute('data-agent-status') !== statusKey);
    });
  }

  function wireListFilters() {
    var group = document.querySelector('[data-status-filter-group]');
    if (!group || group.dataset.wired) return;
    group.dataset.wired = '1';
    group.querySelectorAll('.filter-pills button').forEach(function (btn) {
      btn.addEventListener('click', function () {
        group.querySelectorAll('.filter-pills button').forEach(function (b) { b.classList.remove('active'); });
        btn.classList.add('active');
        filterListRows(STATUS_FILTER_MAP[btn.textContent.trim()] || null);
      });
    });
  }

  function renderLifecycle(m) {
    var el = document.getElementById('opsDashLifecycle');
    if (!el) return;
    var order = ['published', 'review', 'pending', 'dev', 'offline', 'disabled', 'rejected'];
    var max = Math.max.apply(null, order.map(function (k) { return m.counts[k] || 0; }).concat([1]));
    var bars = order.filter(function (k) { return (m.counts[k] || 0) > 0; }).map(function (k) {
      var meta = STATUS_META[k];
      var n = m.counts[k] || 0;
      var pct = Math.round((n / m.total) * 100);
      var h = Math.max(8, Math.round((n / max) * 100));
      return '<div class="ops-dash-bar-item">' +
        '<div class="ops-dash-bar-track"><div class="ops-dash-bar-fill" style="height:' + h + '%;background:' + meta.color + ';"></div></div>' +
        '<div class="ops-dash-bar-num">' + n + '</div>' +
        '<div class="ops-dash-bar-lbl">' + meta.label + '</div>' +
        '<div class="ops-dash-bar-pct">' + pct + '%</div>' +
      '</div>';
    }).join('');
    el.innerHTML = bars || '<p class="ops-dash-empty">暂无智能体</p>';
  }

  function renderSource(m) {
    var el = document.getElementById('opsDashSource');
    if (!el) return;
    var tp = m.thirdparty || 0;
    var pf = m.platform || m.total - tp;
    var tpPct = m.total ? Math.round((tp / m.total) * 100) : 0;
    var pfPct = 100 - tpPct;
    el.innerHTML =
      '<div class="ops-dash-source-row">' +
        '<span><span class="ops-dash-legend-dot" style="background:#2563eb;"></span>平台创建</span>' +
        '<strong>' + pf + ' <small>(' + pfPct + '%)</small></strong>' +
      '</div>' +
      '<div class="ops-dash-source-row">' +
        '<span><span class="ops-dash-legend-dot" style="background:#10b981;"></span>第三方接入</span>' +
        '<strong>' + tp + ' <small>(' + tpPct + '%)</small></strong>' +
      '</div>' +
      '<div class="ops-dash-source-bar">' +
        '<div class="ops-dash-source-seg platform" style="width:' + pfPct + '%;"></div>' +
        '<div class="ops-dash-source-seg thirdparty" style="width:' + tpPct + '%;"></div>' +
      '</div>';
  }

  function renderRuntime(m) {
    var el = document.getElementById('opsDashRuntime');
    if (!el) return;
    var trend = [0.55, 0.62, 0.58, 0.71, 0.85, 0.78, 1].map(function (p) {
      return Math.round(m.calls7d * p);
    });
    var points = trend.map(function (v, i) {
      var x = (i / 6) * 400;
      var y = 100 - (v / Math.max(trend[6], 1)) * 80;
      return x + ',' + y;
    }).join(' ');
    el.innerHTML =
      '<div class="ops-dash-runtime-head"><h4>运行观察摘要</h4><span class="ops-dash-live">近 7 日 · 已上架智能体</span></div>' +
      '<div class="ops-dash-runtime-metrics">' +
        '<div class="ops-dash-meta-item"><span class="ops-dash-meta-val">' + m.calls7d.toLocaleString() + '</span><span class="ops-dash-meta-lbl">对话总量</span></div>' +
        '<div class="ops-dash-meta-item"><span class="ops-dash-meta-val">' + m.timeouts7d + '</span><span class="ops-dash-meta-lbl">超时次数</span></div>' +
        '<div class="ops-dash-meta-item"><span class="ops-dash-meta-val">' + m.latency + '</span><span class="ops-dash-meta-lbl">平均调度延迟</span></div>' +
      '</div>' +
      '<svg class="ops-dash-line-chart ops-dash-runtime-chart" viewBox="0 0 400 100" preserveAspectRatio="none" aria-hidden="true">' +
        '<polyline fill="none" stroke="#2563eb" stroke-width="2" points="' + points + '"/></svg>' +
      '<div class="ops-dash-chart-labels"><span>Day1</span><span>Day3</span><span>Day5</span><span>Day7</span></div>';
  }

  function renderFeed() {
    var el = document.getElementById('opsDashFeed');
    if (!el) return;
    el.innerHTML = FEED_ITEMS.map(function (item) {
      var meta = STATUS_META[item.status] || STATUS_META.dev;
      var st = Proto.resolveAgentListStatus(item.agentId, Proto.DEMO_LIST_AGENTS.findIndex(function (a) { return a.id === item.agentId; }));
      var row = Object.assign({}, item);
      if (st !== item.status && item.agentId) {
        if (st === 'offline') row = Object.assign({}, row, { action: '已下架，用户不可访问', status: 'offline' });
        else if (st === 'disabled') row = Object.assign({}, row, { action: '已停用', status: 'disabled' });
        else if (st === 'published') row = Object.assign({}, row, { action: '已上架运行中', status: 'published' });
        meta = STATUS_META[st] || meta;
      }
      var link = row.reviewLink
        ? Proto.hrefAuditReview({ id: row.agentId, name: row.name, type: 'flow' })
        : (row.link || Proto.href('05-agent-detail.html', { id: row.agentId, name: row.name }));
      return '<div class="ops-dash-feed-item">' +
        '<div class="ops-dash-feed-main">' +
          '<span class="tag ' + meta.class + '" style="font-size:11px;">' + meta.label + '</span>' +
          '<strong>' + row.name + '</strong>' +
          '<span class="ops-dash-feed-action">' + row.action + '</span>' +
        '</div>' +
        '<div class="ops-dash-feed-meta">' + row.time + ' · <a href="' + link + '">查看</a></div>' +
      '</div>';
    }).join('');
  }

  function renderQuickLinks(m) {
    var el = document.getElementById('opsDashQuickLinks');
    if (!el) return;
    el.innerHTML = '<a href="08-audit-queue.html" class="ops-dash-quick">审核工作台' + (m.review ? ' (' + m.review + ')' : '') + '</a>';
  }

  function refresh() {
    if (Proto.ensureDemoAuditQueue) Proto.ensureDemoAuditQueue();
    var m = computeMetrics();
    renderKpis(m);
    renderLifecycle(m);
    renderSource(m);
    renderRuntime(m);
    renderFeed();
    renderQuickLinks(m);
  }

  function confirmOffline(agentId) {
    pendingOfflineId = agentId;
    var mask = document.getElementById('opsOfflineModal');
    if (!mask) {
      Proto.setState({ status: 'offline' }, agentId);
      Proto.toast('已下架');
      Proto.refreshAgentListRow(agentId);
      return;
    }
    mask.classList.add('show');
    mask.setAttribute('aria-hidden', 'false');
  }

  function hideOfflineModal() {
    pendingOfflineId = null;
    var mask = document.getElementById('opsOfflineModal');
    if (mask) {
      mask.classList.remove('show');
      mask.setAttribute('aria-hidden', 'true');
    }
  }

  function wireOfflineModal() {
    var mask = document.getElementById('opsOfflineModal');
    if (!mask || mask.dataset.wired) return;
    mask.dataset.wired = '1';
    mask.querySelectorAll('[data-offline-cancel]').forEach(function (btn) {
      btn.addEventListener('click', hideOfflineModal);
    });
    var confirm = mask.querySelector('[data-offline-confirm]');
    if (confirm) {
      confirm.addEventListener('click', function () {
        if (!pendingOfflineId) return hideOfflineModal();
        Proto.setState({ status: 'offline' }, pendingOfflineId);
        Proto.toast('已下架');
        Proto.refreshAgentListRow(pendingOfflineId);
        hideOfflineModal();
      });
    }
    mask.addEventListener('click', function (e) {
      if (e.target === mask) hideOfflineModal();
    });
  }

  function init() {
    refresh();
    wireOfflineModal();
    wireListFilters();
    if (global.location && global.location.hash === '#agent-list') {
      var params = new URLSearchParams(global.location.search);
      var st = params.get('status');
      if (st) applyStatusFilter(st);
      else scrollToAgentList(null);
    }
  }

  global.OpsListDashboard = {
    init: init,
    refresh: refresh,
    confirmOffline: confirmOffline,
    computeMetrics: computeMetrics,
    applyStatusFilter: applyStatusFilter,
    scrollToAgentList: scrollToAgentList
  };
})(typeof window !== 'undefined' ? window : global);

