/* === 运营列表 BI 看板 === */
.ops-dashboard {
  margin-bottom: 20px; padding: 22px 24px 24px;
  background: linear-gradient(180deg, #f8fafc 0%, #fff 120px);
  border: 1px solid var(--border); border-radius: 12px;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.04);
}
.ops-dash-head {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 18px; flex-wrap: wrap; gap: 8px;
}
.ops-dash-title { font-size: 16px; font-weight: 600; margin: 0; color: var(--text); }
.ops-dash-quicklinks { display: flex; gap: 8px; flex-wrap: wrap; }
.ops-dash-quick {
  font-size: 12px; padding: 6px 14px; border-radius: 999px;
  border: 1px solid #bfdbfe; color: var(--primary); text-decoration: none;
  background: #eff6ff; font-weight: 500; transition: background 0.15s;
}
.ops-dash-quick:hover { background: #dbeafe; }
.ops-dash-kpis {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; margin-bottom: 18px;
}
.ops-dash-kpi-click { cursor: pointer; transition: transform 0.15s, box-shadow 0.15s; }
.ops-dash-kpi-click:hover { transform: translateY(-1px); box-shadow: 0 6px 16px rgba(15, 23, 42, 0.08); }
.ops-dash-kpi {
  display: flex; align-items: flex-start; gap: 14px;
  padding: 18px 20px; border-radius: 12px; border: 1px solid #e8ecf1;
  background: #fff; position: relative; min-height: 88px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}
.ops-dash-kpi-icon {
  width: 44px; height: 44px; border-radius: 12px; display: flex; align-items: center; justify-content: center;
  font-size: 20px; flex-shrink: 0;
}
.ops-dash-kpi-blue .ops-dash-kpi-icon { background: linear-gradient(135deg, #eff6ff, #dbeafe); }
.ops-dash-kpi-orange .ops-dash-kpi-icon { background: linear-gradient(135deg, #fff7ed, #ffedd5); }
.ops-dash-kpi-red .ops-dash-kpi-icon { background: linear-gradient(135deg, #fef2f2, #fee2e2); }
.ops-dash-kpi-yellow .ops-dash-kpi-icon { background: linear-gradient(135deg, #fffbeb, #fef3c7); }
.ops-dash-kpi-label { font-size: 13px; color: #64748b; margin-bottom: 6px; }
.ops-dash-kpi-val { font-size: 28px; font-weight: 700; line-height: 1; color: #0f172a; letter-spacing: -0.02em; }
.ops-dash-pill {
  position: absolute; top: 16px; right: 16px;
  font-size: 11px; padding: 3px 10px; border-radius: 999px; font-weight: 600; text-decoration: none;
}
.ops-dash-pill-blue { background: #eff6ff; color: #2563eb; }
.ops-dash-pill-orange { background: #fff7ed; color: #d97706; }
.ops-dash-pill-red { background: #fef2f2; color: #dc2626; }
.ops-dash-pill-green { background: #ecfdf5; color: #059669; }
.ops-dash-pill-yellow { background: #fffbeb; color: #d97706; }
.ops-dash-panels { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.ops-dash-panel {
  border: 1px solid #e8ecf1; border-radius: 12px;
  background: #fff; padding: 18px 20px;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.05);
}
.ops-dash-panel-chart { min-height: 320px; display: flex; flex-direction: column; }
.ops-dash-panel-head {
  display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px;
}
.ops-dash-panel-head h3 { font-size: 14px; font-weight: 600; margin: 0; color: #0f172a; }
.ops-dash-live {
  font-size: 11px; color: #64748b; background: #f1f5f9;
  padding: 3px 10px; border-radius: 999px;
}
.ops-dash-compliance-body { flex: 1; display: flex; flex-direction: column; }
.ops-dash-donut-wrap {
  display: flex; align-items: center; gap: 24px; padding-bottom: 16px;
  border-bottom: 1px solid #f1f5f9; margin-bottom: 14px;
}
.ops-dash-donut { position: relative; width: 128px; height: 128px; flex-shrink: 0; }
.ops-dash-donut-ring {
  width: 100%; height: 100%; border-radius: 50%;
  background: conic-gradient(#3b82f6 0 35%, #f472b6 35% 70%, #34d399 70% 100%);
  mask: radial-gradient(circle at center, transparent 54%, #000 55%);
  -webkit-mask: radial-gradient(circle at center, transparent 54%, #000 55%);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,0.6);
}
.ops-dash-donut-center {
  position: absolute; inset: 0; display: flex; flex-direction: column;
  align-items: center; justify-content: center; font-size: 22px; font-weight: 700;
  line-height: 1.15; color: #0f172a;
}
.ops-dash-donut-center small { font-size: 10px; font-weight: 400; color: #94a3b8; margin-top: 2px; }
.ops-dash-legend { list-style: none; margin: 0; padding: 0; flex: 1; }
.ops-dash-legend li {
  display: flex; align-items: center; justify-content: space-between;
  font-size: 13px; padding: 8px 0; color: #334155;
}
.ops-dash-legend li strong { font-weight: 600; color: #0f172a; }
.ops-dash-legend-dot {
  width: 8px; height: 8px; border-radius: 50%; margin-right: 10px;
  display: inline-block; vertical-align: middle;
}
.ops-dash-events-title { font-size: 12px; font-weight: 600; color: #64748b; margin-bottom: 10px; }
.ops-dash-event {
  display: flex; align-items: flex-start; gap: 10px; padding: 10px 0;
  border-top: 1px solid #f1f5f9;
}
.ops-dash-event:first-of-type { border-top: none; padding-top: 0; }
.ops-dash-event-icon {
  width: 32px; height: 32px; border-radius: 8px; display: flex; align-items: center; justify-content: center;
  font-size: 14px; flex-shrink: 0;
}
.ops-dash-event-icon-warn { background: #fef2f2; }
.ops-dash-event-icon-danger { background: #fff1f2; }
.ops-dash-event-body { flex: 1; min-width: 0; }
.ops-dash-event-title { font-size: 13px; font-weight: 500; color: #0f172a; margin-bottom: 3px; }
.ops-dash-event-meta { font-size: 11px; color: #94a3b8; }
.ops-dash-event-link {
  font-size: 12px; color: var(--primary); text-decoration: none; white-space: nowrap; padding-top: 2px;
}
.ops-dash-event-link:hover { text-decoration: underline; }
.ops-dash-schedule-chart { flex: 1; }
.ops-dash-chart-legend-top {
  display: flex; justify-content: flex-end; gap: 16px; font-size: 11px; color: #64748b; margin-bottom: 8px;
}
.ops-dash-chart-legend-top span { display: inline-flex; align-items: center; gap: 6px; }
.ops-dash-chart-legend-top .legend-rt i {
  display: inline-block; width: 18px; height: 3px; border-radius: 2px; background: #3b82f6;
}
.ops-dash-chart-legend-top .legend-batch i {
  display: inline-block; width: 18px; height: 0; border-top: 2px dashed #34d399;
}
.ops-dash-trend-chart { width: 100%; height: 140px; display: block; }
.ops-dash-chart-labels {
  display: flex; justify-content: space-between; font-size: 10px; color: #94a3b8;
  padding: 6px 2px 0;
}
.ops-dash-stat-cards {
  display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 14px;
}
.ops-dash-stat-card {
  background: #f8fafc; border: 1px solid #eef2f6; border-radius: 10px;
  padding: 14px 16px; text-align: center;
}
.ops-dash-stat-val { font-size: 24px; font-weight: 700; color: #0f172a; line-height: 1.1; }
.ops-dash-stat-lbl { font-size: 11px; color: #64748b; margin-top: 4px; }
.ops-row-actions { display: flex; flex-wrap: wrap; gap: 4px; align-items: center; }
.ops-actions-cell { white-space: nowrap; }
.ops-act-view { color: var(--primary) !important; border-color: var(--primary) !important; padding: 2px 8px !important; font-size: 12px !important; }
